  if (root.nodeType === Node.TEXT_NODE) {
    rewrite(root as Text, locale);
    return;
  }
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = walker.nextNode(); n !== null; n = walker.nextNode()) rewrite(n as Text, locale);
}

/**
