  const locale = useLocale(user);

  useEffect(() => {
    const root = document.getElementById('root') ?? document.body;
    rewriteAll(root, locale);
    if (locale === 'en') return;
    const observer = new MutationObserver((records) => {
      for (const r of records) {
        if (r.type === 'characterData') {
